/**
 * GET /api/reports/student-dossier-report?student_id=...&format=json|pdf
 * FEATURE 5 — a report about ONE student, generated by their mentor.
 *
 * Pulls together Form A (Feature 1), the semester GPA trend when the
 * student allows it (Feature 2), achievements (Feature 6), full query
 * history and the resolution-confirmation record (Feature 3).
 *
 * Access is isAssignedMentor-guarded inside get_student_dossier(); the
 * HOD may view any student, and a student may view their own.
 */
import { withApiDefaults, sendSuccess, ApiError } from '../_lib/http-response.js';
import { requireAuthenticatedUser, enforceRateLimit, recordAuditEntry } from '../_lib/request-guards.js';
import { parseOrThrow, studentReportQuerySchema } from '../_lib/input-validation.js';
import { buildStudentDossierPdf } from '../_lib/report-document-builder.js';

export default withApiDefaults(['GET'], async (req, res) => {
  const context = await requireAuthenticatedUser(req);
  await enforceRateLimit(context, { key: 'student-report', max: 30, windowSeconds: 60 });

  const query = parseOrThrow(studentReportQuerySchema, {
    student_id: req.query.student_id,
    format: req.query.format || 'json'
  });

  const { data: report, error } = await context.asUser.rpc('get_student_dossier', {
    p_student_id: query.student_id
  });
  if (error) throw new ApiError(error.message, error.code === '42501' ? 403 : 400);
  if (!report) throw new ApiError('No report data was returned', 404);

  if (query.format === 'json') {
    return sendSuccess(res, 'Student report generated', { report });
  }

  const pdfBytes = await buildStudentDossierPdf(report);
  const safeName = String(report.student.name).replace(/[^a-z0-9]+/gi, '-').toLowerCase();
  const filename = `student-report-${safeName}-${new Date().toISOString().slice(0, 10)}.pdf`;

  await recordAuditEntry(context, req, 'report.student_dossier_pdf', {
    type: 'user_profiles', id: report.student.id,
    metadata: { gpa_included: report.gpa_shared }
  });

  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
  res.setHeader('Content-Length', String(pdfBytes.length));
  res.status(200).send(pdfBytes);
});
